fn pair_hits(h: Int, ys: List[Int], t: Int) -> Int
  requires distinct(ys)
  ensures result == (count j in 0..len(ys): h + ys[j] == t)
  effects pure
  example pair_hits(1, [4, 3], 5) == 1
  example pair_hits(2, [3, 4], 5) == 1
  example pair_hits(2, [], 5) == 0
{
  match ys {
    [] => 0
    [y, ..rest] => (if h + y == t then 1 else 0) + pair_hits(h, rest, t)
  }
}

fn count_pairs_sum(xs: List[Int], t: Int) -> Int
  requires distinct(xs)
  ensures result == (sum i in 0..len(xs): (count j in i + 1..len(xs): xs[i] + xs[j] == t))
  effects pure
  example count_pairs_sum([1, 2, 3, 4], 5) == 2
  example count_pairs_sum([1, 2], 9) == 0
  example count_pairs_sum([], 0) == 0
{
  match xs {
    [] => 0
    [h, ..rest] => pair_hits(h, rest, t) + count_pairs_sum(rest, t)
  }
}

